I === \"1\")\n        return false;\n    if (!process.stdout.isTTY)\n        return true;\n    if (env.CI)\n        return true;\n    // Known coding-agent env vars. These are best-effort — the isTTY check\n    // above already catches most cases since agents typically pipe stdout.\n    if (env.CLAUDECODE ||\n        env.CLAUDE_CODE_ENTRYPOINT ||\n        env.CURSOR_AGENT ||\n        env.AIDER_MODEL ||\n        env.CODEX_CLI)\n        return true;\n    return false;\n};\n//# sourceMappingURL=interactive.js.map","import * as Clock from \"effect/Clock\";\nimport * as Data from \"effect/Data\";\nimport * as Duration from \"effect/Duration\";\nimport * as Effect from \"effect/Effect\";\nimport * as FileSystem from \"effect/FileSystem\";\nimport * as Option from \"effect/Option\";\nimport * as Path from \"effect/Path\";\nimport * as Schedule from \"effect/Schedule\";\nimport * as Semaphore from \"effect/Semaphore\";\nimport { rootDir } from \"./Profile.js\";\nconst semaphores = new Map();\n// Keep STALE well above REFRESH — a saturated machine can starve the\n// heartbeat fiber for seconds.\nconst STALE = Duration.seconds(30);\nconst REFRESH = Duration.seconds(10);\nconst RETRY_INTERVAL = Duration.millis(50);\nconst DEFAULT_TIMEOUT = Duration.minutes(2);\nclass LockHeld extends Data.TaggedError(\"LockHeld\") {\n}\nclass LockTimeo